CREATE OR REPLACE FUNCTION public.daily_followups_guard_insert()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_existing_id text;
  v_phone text;
  v_is_open boolean;
begin
  new.identity_key := public.build_followup_identity_key(
    new.customer_id,
    new.customer_code,
    coalesce(new.customer_phone, new.phone),
    coalesce(new.customer_name, new.name)
  );

  v_phone := public.normalize_followup_phone(coalesce(new.customer_phone, new.phone, ''));
  v_is_open := new.completed_at is null
    and new.cancelled_at is null
    and new.archived_at is null
    and lower(coalesce(new.status, '')) not in ('completed','cancelled','archived','closed','merged_duplicate')
    and lower(coalesce(new.followup_status, '')) not in ('completed','تم','تم التواصل','تم الشراء بعد المتابعة');

  if v_is_open and new.identity_key is not null then
    select id into v_existing_id
    from public.daily_followups
    where identity_key = new.identity_key
      and coalesce(nullif(trim(branch), ''), 'غير محدد') = coalesce(nullif(trim(new.branch), ''), 'غير محدد')
      and coalesce(is_hidden, false) = false
      and coalesce(is_duplicate, false) = false
      and duplicate_of is null
      and completed_at is null
      and cancelled_at is null
      and archived_at is null
      and lower(coalesce(status, '')) not in ('completed','cancelled','archived','closed','merged_duplicate')
      and lower(coalesce(followup_status, '')) not in ('completed','تم','تم التواصل','تم الشراء بعد المتابعة')
    order by coalesce(updated_at, created_at, now()) desc, created_at desc nulls last
    limit 1;

    if v_existing_id is not null then
      new.is_duplicate := true;
      new.duplicate_of := v_existing_id;
      new.duplicate_reason := coalesce(nullif(new.duplicate_reason, ''), 'تم ربط الطلب تلقائيًا بمتابعة مفتوحة قائمة');
      new.duplicate_archived_at := coalesce(new.duplicate_archived_at, now());
      new.archived_at := coalesce(new.archived_at, now());
      new.archive_reason := coalesce(nullif(new.archive_reason, ''), 'طلب مرتبط بالمتابعة الأساسية ' || v_existing_id);
      new.is_hidden := true;
      new.hidden_at := coalesce(new.hidden_at, now());
      new.hidden_reason := coalesce(nullif(new.hidden_reason, ''), 'duplicate_merged_into:' || v_existing_id);
      new.status := 'merged_duplicate';
      new.followup_status := 'merged_duplicate';
      new.request_status := 'merged_duplicate';
      new.updated_at := now();
      return new;
    end if;
  end if;

  if v_phone = '' or not (v_phone ~ '^01[0125][0-9]{8}$') then
    new.contact_status := coalesce(nullif(new.contact_status, ''), 'invalid_phone');
  end if;

  if v_is_open
     and new.next_followup_date is null
     and lower(coalesce(new.contact_status, '')) not in ('invalid_phone','الرقم غير صحيح') then
    new.next_followup_date := coalesce(new.followup_datetime::date, nullif(new.followup_date, '')::date, current_date);
  end if;

  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.dawaa_guard_daily_followup_state_v2()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_catalog'
AS $function$
declare
  v_status text := lower(trim(coalesce(new.followup_status,new.status,'')));
  v_result text := nullif(trim(coalesce(new.followup_result,new.contact_result,'')),'');
  v_summary text := nullif(trim(coalesce(new.evaluation_summary,new.followup_summary,new.followup_notes,'')),'');
  v_today date := (now() at time zone 'Africa/Cairo')::date;
  v_completed boolean := v_status in ('تم','مكتمل','completed','done');
  v_cancelled boolean := v_status in ('ملغي','ملغى','cancelled','canceled') or new.cancelled_at is not null;
  v_postponed boolean := v_status in ('مؤجل','postponed') or new.postponed_until is not null;
  v_old_status text;
  v_old_completed boolean := false;
  v_old_cancelled boolean := false;
  v_old_postponed boolean := false;
  v_enter_hidden boolean;
  v_validate_cancelled boolean;
  v_validate_postponed boolean;
  v_validate_completed boolean;
begin
  if current_setting('dawaa.historical_import',true)='on' then return new; end if;
  new.updated_at := now();

  if tg_op='UPDATE' then
    v_old_status := lower(trim(coalesce(old.followup_status,old.status,'')));
    v_old_completed := v_old_status in ('تم','مكتمل','completed','done') or old.completed_at is not null;
    v_old_cancelled := v_old_status in ('ملغي','ملغى','cancelled','canceled') or old.cancelled_at is not null;
    v_old_postponed := v_old_status in ('مؤجل','postponed') or old.postponed_until is not null;
  end if;

  v_enter_hidden := coalesce(new.is_hidden,false) and (
    tg_op='INSERT' or not coalesce(old.is_hidden,false)
    or new.hidden_reason is distinct from old.hidden_reason
    or new.archive_reason is distinct from old.archive_reason
  );

  v_validate_cancelled := v_cancelled and (
    tg_op='INSERT' or not v_old_cancelled
    or new.cancelled_reason is distinct from old.cancelled_reason
    or new.cancelled_at is distinct from old.cancelled_at
  );

  v_validate_postponed := v_postponed and not v_cancelled and not v_completed and (
    tg_op='INSERT' or not v_old_postponed
    or new.postponed_until is distinct from old.postponed_until
    or new.next_followup_date is distinct from old.next_followup_date
  );

  v_validate_completed := v_completed and not v_cancelled and (
    tg_op='INSERT' or not v_old_completed
    or new.completed_at is distinct from old.completed_at
    or new.followup_result is distinct from old.followup_result
    or new.contact_result is distinct from old.contact_result
    or new.followup_summary is distinct from old.followup_summary
    or new.evaluation_summary is distinct from old.evaluation_summary
    or new.followup_notes is distinct from old.followup_notes
  );

  if v_enter_hidden then
    if nullif(trim(coalesce(new.hidden_reason,new.archive_reason,'')),'') is null then
      raise exception 'سبب الأرشفة مطلوب قبل إخفاء المتابعة';
    end if;
    new.hidden_at := coalesce(new.hidden_at,new.archived_at,now());
    new.archived_at := coalesce(new.archived_at,new.hidden_at);
    new.hidden_reason := coalesce(nullif(trim(new.hidden_reason),''),nullif(trim(new.archive_reason),''));
    new.archive_reason := coalesce(nullif(trim(new.archive_reason),''),nullif(trim(new.hidden_reason),''));
  end if;

  if v_validate_cancelled then
    if nullif(trim(coalesce(new.cancelled_reason,new.followup_notes,'')),'') is null then
      raise exception 'سبب إلغاء المتابعة مطلوب';
    end if;
    new.cancelled_at := coalesce(new.cancelled_at,now());
    new.cancelled_reason := coalesce(nullif(trim(new.cancelled_reason),''),nullif(trim(new.followup_notes),''));
    new.status := 'ملغي';
    new.followup_status := 'ملغي';
  end if;

  if v_validate_postponed then
    if new.postponed_until is null and new.next_followup_date is null then
      raise exception 'حدد موعد التأجيل أو تاريخ المتابعة القادمة';
    end if;
    if new.postponed_until is not null and new.postponed_until<=now() then
      raise exception 'موعد التأجيل يجب أن يكون في المستقبل';
    end if;
    if new.next_followup_date is not null and new.next_followup_date<v_today then
      raise exception 'تاريخ المتابعة القادمة لا يمكن أن يكون في الماضي';
    end if;
    if new.postponed_until is not null then
      new.next_followup_date := (new.postponed_until at time zone 'Africa/Cairo')::date;
    end if;
    new.needs_next_followup := true;
    new.completed_at := null;
    new.status := 'مؤجل';
    new.followup_status := 'مؤجل';
  end if;

  if v_validate_completed then
    if v_result is null then raise exception 'نتيجة المتابعة مطلوبة قبل الإغلاق'; end if;
    if v_summary is null or length(v_summary)<10 then
      raise exception 'اكتب ملخصًا واضحًا للمتابعة لا يقل عن 10 أحرف قبل الإغلاق';
    end if;
    new.completed_at := coalesce(new.completed_at,now());
    new.evaluation_summary := coalesce(nullif(trim(new.evaluation_summary),''),v_summary);
    new.followup_summary := coalesce(nullif(trim(new.followup_summary),''),v_summary);
    new.status := 'تم';
    new.followup_status := 'تم';
  end if;

  return new;
end
$function$

CREATE OR REPLACE FUNCTION public.normalize_customer_service_branch_owner()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  normalized_branch text;
  canonical_owner text;
begin
  normalized_branch := trim(coalesce(new.branch, ''));

  if normalized_branch in ('الشامي', 'فرع الشامي', 'شامي') then
    new.branch := 'فرع الشامي';
    canonical_owner := 'د/ ضحى';
  elsif normalized_branch in ('شكري', 'فرع شكري', 'شكرى', 'فرع شكرى') then
    new.branch := 'فرع شكري';
    canonical_owner := 'د/ دنيا';
  else
    return new;
  end if;

  -- The customer-service owner is fixed by branch.
  -- Keep assigned_doctor unchanged because it may hold the doctor who requested the follow-up.
  new.responsible_name := canonical_owner;
  new.assigned_to := canonical_owner;

  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.trg_followup_dedupe_same_day()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_dup_exists boolean;
begin
  if new.assigned_doctor is not null and new.customer_code is not null then
    select exists(
      select 1 from public.daily_followups f
      where f.id <> new.id
        and f.assigned_doctor = new.assigned_doctor
        and f.customer_code = new.customer_code
        and f.created_at::date = new.created_at::date
        and coalesce(f.counts_toward_quota, true) = true
    ) into v_dup_exists;

    if v_dup_exists then
      new.counts_toward_quota := false;
      new.is_flagged := true;
      new.flag_reason := 'تكرار نفس العميل في نفس اليوم';
    end if;
  end if;
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.validate_daily_followup_write()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_status text := lower(coalesce(new.status, ''));
  v_followup_status text := lower(coalesce(new.followup_status, ''));
  v_result text := trim(coalesce(new.followup_result, new.contact_result, ''));
  v_phone text := public.normalize_followup_phone(coalesce(new.customer_phone, new.phone, ''));
  v_is_final boolean;
begin
  v_is_final := new.completed_at is not null
    or v_status in ('completed','closed')
    or v_followup_status in ('completed','تم','تم التواصل','تم الشراء بعد المتابعة');

  if v_is_final and v_result = '' then
    raise exception 'لا يمكن إغلاق المتابعة بدون نتيجة رسمية واضحة';
  end if;

  if v_phone = '' or not (v_phone ~ '^01[0125][0-9]{8}$') then
    new.contact_status := coalesce(nullif(new.contact_status, ''), 'invalid_phone');
  end if;

  if not v_is_final
     and new.cancelled_at is null
     and new.archived_at is null
     and coalesce(new.is_hidden, false) = false
     and coalesce(new.is_duplicate, false) = false
     and new.next_followup_date is null
     and lower(coalesce(new.contact_status, '')) not in ('invalid_phone','الرقم غير صحيح') then
    new.next_followup_date := coalesce(new.followup_datetime::date, nullif(new.followup_date, '')::date, current_date);
  end if;

  return new;
end;
$function$
